1670	\begin{lemma}
1671	  \label{lem:chernoff-bernoulli-matrix}
1672	  Let $0 < \theta < 1$ and let $k, d > 0$ be integers such that $k \geq 2d/\theta$.
1673	  Define the matrix-valued function $F$ by
1674	  \[ F(X) = \sum_{r = d+1}^{k} \binom{k}{r} X^r (I - X)^{r - k}. \]
1675	  Then for any Hermitian matrix $X$ such that $0 \leq X \leq I$ and $\bra{\psi} X \ot I
1676	  \ket{\psi} \geq 1 - \kappa$, it holds that
1677	  \[ \bra{\psi} F(X) \ot I \ket{\psi} \geq 1 - \frac{\kappa}{1 - \theta}
1678	    - e^{-\theta^2 k/2}. \]
1679	  \end{lemma}
1680	  \begin{proof}
1681	    Let $\rho$ be the reduced state of $\ket{\psi}$ on one prover's
1682	    subsystem (since the state is assumed to be symmetric, it does not
1683	    matter which prover we take).
1684	    Write the eigendecomposition $X = \sum_{i} \lambda_i
1685	    \ket{v_i}\bra{v_i}$ of $X$, where we allow some of the
1686	    eigenvalues to be $0$ so that the set of eigenvectors
1687	    $\{\ket{v_i}\}$ forms an orthonormal basis of the space. This defines a probability
1688	    distribution $\mu$ over eigenvectors, where eigenvector $i$
1689	    occurs with probability $\mu(i) = \bra{v_i} \rho \ket{v_i}$. The
1690	    given condition $\bra{\psi} X \ot I \ket{\psi} = \Tr(X \rho) \geq
1691	    1 -\kappa$ implies that
1692	    \begin{align*}
1693	      \E_{\bi \sim \mu} \lambda_{\bi}
1694	      = \sum_i \lambda_i \cdot \mu(i)
1695	       &= \sum_i \lambda_i \cdot \bra{v_i} \rho \ket{v_i}\\
1696	       &=\sum_i \lambda_i \cdot \tr(\ket{v_i} \bra{v_i}  \cdot \rho)\\
1697	       &=\tr \Big(\sum_i \lambda_i  \ket{v_i} \bra{v_i} \cdot\rho\Big)
1698	       = \tr(X \rho)
1699	       \geq 1 - \kappa.
1700	     \end{align*}
1701	     Or, equivalently,
1702	     \begin{equation*}
1703	      \E_{\bi \sim \mu} ( 1 -\lambda_{\bi}) \leq \kappa.
1704	    \end{equation*}
1705	      By Markov's inequality, for any $0 < \theta < 1$, we have
1706	     \begin{equation*}
1707	     \Pr_{\bi \sim \mu}[(1-\lambda_{\bi}) \geq (1 - \theta)]
1708	     \leq \frac{\E_{\bi \sim \mu} (1-\lambda_{\bi})}{1-\theta}
1709	     \leq \frac{\kappa}{1-\theta}.
1710	     \end{equation*} 
1711	     In other words,
1712	     \begin{equation}\label{eq:in-other-words}
1713	     \Pr_{\bi \sim \mu}[\lambda_{\bi} > \theta]
1714	     = \Pr_{\bi \sim \mu}[(1 - \lambda_{\bi}) < (1 - \theta)]
1715	     = 1 - \Pr_{\bi \sim \mu}[(1 - \lambda_{\bi}) \geq (1 - \theta)]
1716	     \geq 1 - \frac{\kappa}{1-\theta}.  
1717	     \end{equation}
1718	      Thus, it  holds that with probability at least $1 - \frac{\kappa}{1 - \theta}$ over $\bi \sim
1719	    \mu$, $\lambda_{\bi} > \theta$.
1720	
